def shortest_path(graph, source, target):
    # If target is not in the graph, the path is unreachable)
    if target not in graph: 
        return float('inf'), None)  # or return (float('inf'), None)

    # Priority queue for BFS/DFS
    queue = [(0, [source])]  # (distance, path) format
    visited = set()

    while queue:
        (distance, path) = heappop(queue)

        if path[-1] == target:
            return (distance, path)

        if path[-1] in visited:
            continue
        visited.add(path[-1])

        for neighbor, weight in graph.get(path[-1], []):
            if neighbor not in visited:
                new_path = path + [neighbor]
                new_distance = distance + weight
                heappush(queue, (new_distance, new_path))

    return float('inf'), None

