    queue = [(0, source, [source])]
    priority_queue = [(0, source)]
    while priority_queue:
        dist, node = heapq.heappop(priority_queue)
        if node == target:
            return (dist, queue[node])
        if node in graph:
            for neighbor, weight in graph[node]:
                if neighbor not in (node, target):
                    total_dist = dist + weight
                    if (total_dist, neighbor) not in priority_queue:
                        heapq.heappush(priority_queue, (total_dist, neighbor))
                        heapq.heappush(queue, (total_dist, neighbor, queue[node] + [neighbor]))
    return (float('inf'), None)
