            current_distance, current_node = heapq.heappop(priority_queue)
            if current_distance > distances[current_node]:
                continue
            for neighbor, weight in graph.get(current_node, []):
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))
        return distances[end]
    if target not in graph:
        return (float('inf'), None)
    shortest_distance = dijkstra_shortest_path(graph, source, target)
    if shortest_distance == math.inf:
        return (float('inf'), None)

    def reconstruct_path(graph, start, end):
        path = []
        current_node = end
        while current_node != start:
            for neighbor, weight in graph.get(current_node, []):
                if neighbor == start:
                    path.append(neighbor)
                    current_node = start
                    break
                elif graph[current_node][0][1] + graph[neighbor][0][1] == distances[end]:
                    path.append(neighbor)
                    current_node = neighbor
                    break
            else:
                current_node = start
                break
        path.append(start)
        path.reverse()
        return path
    return (shortest_distance, reconstruct_path(graph, source, target))
